import * as THREE from 'three';
import { createScene } from './data/object.js';
import * as fs from 'fs';

/**
 * Convert Three.js scene to OBJ format with Blender Z-up coordinate system
 * Applies -90 degree X-rotation to convert from Y-up to Z-up
 */

class OBJExporter {
  constructor() {
    this.vertexIndex = 1; // OBJ indices start at 1
    this.output = '';
  }

  /**
   * Export a Three.js Object3D hierarchy to OBJ format
   */
  parse(scene) {
    const vertices = [];
    const faces = [];

    // Apply -90 degree X-rotation to convert Y-up to Z-up (Blender coordinate system)
    const blenderRotation = new THREE.Matrix4().makeRotationX(-Math.PI / 2);

    // Traverse the scene and collect all meshes
    scene.traverse((object) => {
      if (object.isMesh) {
        this.processMesh(object, vertices, faces, blenderRotation);
      } else if (object.isInstancedMesh) {
        this.processInstancedMesh(object, vertices, faces, blenderRotation);
      }
    });

    // Write vertices
    this.output += '# Vertices\n';
    for (const vertex of vertices) {
      this.output += `v ${vertex.x.toFixed(6)} ${vertex.y.toFixed(6)} ${vertex.z.toFixed(6)}\n`;
    }

    this.output += '\n# Faces\n';
    for (const face of faces) {
      this.output += `f ${face[0]} ${face[1]} ${face[2]}\n`;
    }

    return this.output;
  }

  /**
   * Process a regular mesh
   */
  processMesh(mesh, vertices, faces, blenderRotation) {
    const geometry = mesh.geometry;

    if (!geometry.isBufferGeometry) {
      console.warn('Skipping non-BufferGeometry mesh:', mesh.name);
      return;
    }

    // Clone geometry to avoid modifying original
    const geometryClone = geometry.clone();

    // Get world matrix for this mesh
    mesh.updateMatrixWorld(true);
    const worldMatrix = mesh.matrixWorld.clone();

    // Apply Blender rotation after world transform
    worldMatrix.premultiply(blenderRotation);

    // Apply transformations to geometry
    geometryClone.applyMatrix4(worldMatrix);

    // Get position attribute
    const positionAttribute = geometryClone.getAttribute('position');
    if (!positionAttribute) {
      console.warn('No position attribute found in mesh:', mesh.name);
      return;
    }

    const startIndex = this.vertexIndex;

    // Add vertices
    for (let i = 0; i < positionAttribute.count; i++) {
      const vertex = new THREE.Vector3(
        positionAttribute.getX(i),
        positionAttribute.getY(i),
        positionAttribute.getZ(i)
      );
      vertices.push(vertex);
    }

    // Add faces
    const index = geometryClone.index;
    if (index) {
      // Indexed geometry
      for (let i = 0; i < index.count; i += 3) {
        faces.push([
          startIndex + index.getX(i),
          startIndex + index.getX(i + 1),
          startIndex + index.getX(i + 2)
        ]);
      }
    } else {
      // Non-indexed geometry
      for (let i = 0; i < positionAttribute.count; i += 3) {
        faces.push([
          startIndex + i,
          startIndex + i + 1,
          startIndex + i + 2
        ]);
      }
    }

    this.vertexIndex += positionAttribute.count;
  }

  /**
   * Process an instanced mesh (used for axis pins)
   */
  processInstancedMesh(instancedMesh, vertices, faces, blenderRotation) {
    const geometry = instancedMesh.geometry;
    const count = instancedMesh.count;

    if (!geometry.isBufferGeometry) {
      console.warn('Skipping non-BufferGeometry instanced mesh:', instancedMesh.name);
      return;
    }

    // Get base world matrix for the instanced mesh
    instancedMesh.updateMatrixWorld(true);
    const baseWorldMatrix = instancedMesh.matrixWorld.clone();

    // Process each instance
    const instanceMatrix = new THREE.Matrix4();

    for (let i = 0; i < count; i++) {
      // Get instance matrix
      instancedMesh.getMatrixAt(i, instanceMatrix);

      // Clone geometry for this instance
      const geometryClone = geometry.clone();

      // Combine transforms: instance transform -> world transform -> Blender rotation
      const finalMatrix = new THREE.Matrix4();
      finalMatrix.copy(baseWorldMatrix).multiply(instanceMatrix);
      finalMatrix.premultiply(blenderRotation);

      // Apply transformations
      geometryClone.applyMatrix4(finalMatrix);

      // Get position attribute
      const positionAttribute = geometryClone.getAttribute('position');
      if (!positionAttribute) {
        continue;
      }

      const startIndex = this.vertexIndex;

      // Add vertices
      for (let j = 0; j < positionAttribute.count; j++) {
        const vertex = new THREE.Vector3(
          positionAttribute.getX(j),
          positionAttribute.getY(j),
          positionAttribute.getZ(j)
        );
        vertices.push(vertex);
      }

      // Add faces
      const index = geometryClone.index;
      if (index) {
        for (let j = 0; j < index.count; j += 3) {
          faces.push([
            startIndex + index.getX(j),
            startIndex + index.getX(j + 1),
            startIndex + index.getX(j + 2)
          ]);
        }
      } else {
        for (let j = 0; j < positionAttribute.count; j += 3) {
          faces.push([
            startIndex + j,
            startIndex + j + 1,
            startIndex + j + 2
          ]);
        }
      }

      this.vertexIndex += positionAttribute.count;
    }
  }
}

// Main execution
async function main() {
  console.log('Creating Three.js scene...');
  const scene = createScene();

  console.log('Exporting to OBJ format with Blender Z-up coordinate system...');
  const exporter = new OBJExporter();
  const objContent = exporter.parse(scene);

  const outputPath = '/root/output/object.obj';
  console.log(`Writing OBJ file to ${outputPath}...`);
  fs.writeFileSync(outputPath, objContent);

  console.log('Export complete!');
  console.log(`Total vertices: ${exporter.vertexIndex - 1}`);
}

main().catch(error => {
  console.error('Export failed:', error);
  process.exit(1);
});

