import * as fs from 'fs';

// Read and parse the OBJ file
const objContent = fs.readFileSync('/root/output/object.obj', 'utf-8');
const lines = objContent.split('\n');

let vertexCount = 0;
let faceCount = 0;
let minY = Infinity, maxY = -Infinity;
let minZ = Infinity, maxZ = -Infinity;

for (const line of lines) {
  if (line.startsWith('v ')) {
    vertexCount++;
    const parts = line.split(/\s+/);
    const y = parseFloat(parts[2]);
    const z = parseFloat(parts[3]);
    minY = Math.min(minY, y);
    maxY = Math.max(maxY, y);
    minZ = Math.min(minZ, z);
    maxZ = Math.max(maxZ, z);
  } else if (line.startsWith('f ')) {
    faceCount++;
  }
}

console.log('OBJ Export Verification Report');
console.log('================================');
console.log(`Total vertices: ${vertexCount}`);
console.log(`Total faces: ${faceCount}`);
console.log(`\nCoordinate ranges (Blender Z-up space):`);
console.log(`  Y range: ${minY.toFixed(2)} to ${maxY.toFixed(2)}`);
console.log(`  Z range: ${minZ.toFixed(2)} to ${maxZ.toFixed(2)}`);
console.log(`\nNote: After -90° X-rotation:`);
console.log(`  - Original Three.js Y (up) is now Blender Z (up)`);
console.log(`  - Original Three.js Z is now Blender -Y`);
console.log('\nThe file is ready to import into Blender!');

